using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text;

using Decimal128.TextCodec;

namespace Decimal128.TextCodec.Tests;

/// <summary>
/// The four conformance tables, over the shared <c>text_bid_dpd</c> corpus.
/// </summary>
/// <remarks>
/// <para>
/// The vectors are read straight out of <c>resources/text_bid_dpd</c> — the
/// <c>decimal128-resources</c> submodule — and were generated by the
/// <c>decimal128-c</c> engine through its public API. That engine reaches its
/// answers by different algorithms than this codec does, so agreement is a
/// cross-check rather than a tautology.
/// </para>
/// <code>
///   T1 DECODE  bid -> text and dpd -> text          (100, noncanonical)
///   T2 ENCODE  text -> bid and text -> dpd          (100)
///   T3 PARSE   input text -> bits, both formats     (parse, 1,061 rows)
///   T4 ERROR   malformed input text -> rejection    (error, 173 rows)
/// </code>
/// <para>
/// Plus the cross-format assertion: for every row both encodings must render to
/// the same text. That is the strongest property the corpus encodes.
/// </para>
/// <para>
/// The fifth table, <c>canonical</c>, is 84,783 rows of mostly common-path
/// volume and runs as <see cref="TestCanonicalCorpus"/>, the second class in
/// this file.
/// </para>
/// <para>
/// The sibling ports pass a failure message to every assertion. xunit's
/// <c>Assert.Equal</c> takes none, so each row test is written as an explicit
/// comparison and an <c>Assert.Fail</c>, which also keeps the 84,783-row table
/// from formatting a message it will not use.
/// </para>
/// </remarks>
public class TestCorpusVectors
{
    /// <summary>T1: every row's two encodings must render to the expected text.</summary>
    [Fact]
    public void HundredDecodes()
    {
        var rows = Corpus.Load(Corpus.Hundred);
        Assert.Equal(100, rows.Count);
        RunDecodeTable(rows, "100");
    }

    /// <summary>T2: and the text must encode back to the same bits.</summary>
    [Fact]
    public void HundredReEncodes()
    {
        var rows = Corpus.Load(Corpus.Hundred);
        Assert.Equal(100, rows.Count);
        RunEncodeTable(rows, "100");
    }

    /// <summary>
    /// One-way rows: both encodings decode to the text, but at least one is a
    /// bit pattern the canonical encoder would never emit, so re-encoding is
    /// deliberately not asserted.
    /// </summary>
    [Fact]
    public void NonCanonicalEncodingsRenderCorrectly()
    {
        var rows = Corpus.Load(Corpus.NonCanonical);
        Assert.Equal(1267, rows.Count);
        RunDecodeTable(rows, "noncanonical");
    }

    /// <summary>T3: the only table that reaches the rounding surface at all.</summary>
    [Fact]
    public void ParseVectorsProduceBothEncodings()
    {
        var rows = Corpus.Load(Corpus.Parse);
        Assert.Equal(1061, rows.Count);
        foreach (var row in rows)
        {
            var b = ParseResult.BidParse(row.Text);
            if (b.Error != null)
                Assert.Fail($"parse line {row.LineNumber}: bid rejected <{row.Text}>: {b.Error}");
            if (b.Bits != row.Bid)
                Assert.Fail($"parse line {row.LineNumber}: bid <{row.Text}> gave {Hex.Format32(b.Bits)}, expected {row.BidHex}");
            var d = ParseResult.DpdParse(row.Text);
            if (d.Error != null)
                Assert.Fail($"parse line {row.LineNumber}: dpd rejected <{row.Text}>: {d.Error}");
            if (d.Bits != row.Dpd)
                Assert.Fail($"parse line {row.LineNumber}: dpd <{row.Text}> gave {Hex.Format32(d.Bits)}, expected {row.DpdHex}");
        }
    }

    /// <summary>
    /// T4: malformed input. Both formats must reject, must agree on the
    /// message, and must still have written the canonical positive quiet NaN —
    /// the corpus carries that pattern in its bits columns precisely so a port
    /// can assert the written value and not merely the rejection. Here the
    /// writing itself is guaranteed by the <c>out</c> parameter; what the
    /// assertion adds is that the value written is the right one.
    /// </summary>
    [Fact]
    public void ErrorVectorsAreRejectedByBothFormats()
    {
        var rows = Corpus.Load(Corpus.Error);
        Assert.Equal(173, rows.Count);
        foreach (var row in rows)
        {
            var b = ParseResult.BidParse(row.Text);
            var d = ParseResult.DpdParse(row.Text);
            if (b.Error == null)
                Assert.Fail($"error line {row.LineNumber}: bid ACCEPTED <{row.Text}>, corpus says {row.Status}");
            if (d.Error == null)
                Assert.Fail($"error line {row.LineNumber}: dpd ACCEPTED <{row.Text}>, corpus says {row.Status}");
            if (b.Error != d.Error)
                Assert.Fail($"error line {row.LineNumber}: the formats disagree on <{row.Text}>: <{b.Error}> vs <{d.Error}>");
            if (b.Bits != row.Bid)
                Assert.Fail($"error line {row.LineNumber}: bid <{row.Text}> left {Hex.Format32(b.Bits)}, expected {row.BidHex}");
            if (d.Bits != row.Bid)
                Assert.Fail($"error line {row.LineNumber}: dpd <{row.Text}> left {Hex.Format32(d.Bits)}, expected {row.BidHex}");
        }
    }

    /// <summary>
    /// The reader itself. <c>parse</c> and <c>error</c> quote their text
    /// column, and the four rows below are exactly the ones a naive comma split
    /// corrupts while still passing — a mangled malformed input fails to parse
    /// either way.
    /// </summary>
    [Fact]
    public void QuotedColumnRoundTrips()
    {
        var texts = Corpus.Load(Corpus.Error).Select(r => r.Text).ToHashSet();
        Assert.True(texts.Contains(""), "the empty-string row was lost");
        Assert.True(texts.Any(t => t.StartsWith(' ')), "a leading-space row was lost");
        Assert.True(texts.Any(t => t.EndsWith(' ')), "a trailing-space row was lost");
        Assert.True(texts.Any(t => t.Contains(',')), "an embedded-comma row was lost");
    }

    /// <summary>
    /// Every row: both encodings must render to the expected text, and
    /// therefore to each other.
    /// </summary>
    internal static void RunDecodeTable(IReadOnlyList<CorpusRow> rows, string label)
    {
        byte[] buf = new byte[Decimal128TextCodec.MaxLen];
        foreach (var row in rows)
        {
            string bidText = Decimal128TextCodec.Bid128ToString(row.Bid);
            if (bidText != row.Text)
                Assert.Fail($"{label} line {row.LineNumber}: bid #{row.BidHex} rendered <{bidText}>, expected <{row.Text}>");
            string dpdText = Decimal128TextCodec.Dpd128ToString(row.Dpd);
            if (dpdText != row.Text)
                Assert.Fail($"{label} line {row.LineNumber}: dpd #{row.DpdHex} rendered <{dpdText}>, expected <{row.Text}>");
            int bidLen = Decimal128TextCodec.Bid128ToString(buf, row.Bid);
            string bidBuf = Encoding.Latin1.GetString(buf, 0, bidLen);
            if (bidBuf != row.Text)
                Assert.Fail($"{label} line {row.LineNumber}: bid into buffer #{row.BidHex} rendered <{bidBuf}>, expected <{row.Text}>");
            int dpdLen = Decimal128TextCodec.Dpd128ToString(buf, row.Dpd);
            string dpdBuf = Encoding.Latin1.GetString(buf, 0, dpdLen);
            if (dpdBuf != row.Text)
                Assert.Fail($"{label} line {row.LineNumber}: dpd into buffer #{row.DpdHex} rendered <{dpdBuf}>, expected <{row.Text}>");
        }
    }

    /// <summary>Round-trippable rows: the text must encode back to the same bits.</summary>
    internal static void RunEncodeTable(IReadOnlyList<CorpusRow> rows, string label)
    {
        foreach (var row in rows)
        {
            var b = ParseResult.BidParse(row.Text);
            if (b.Error != null)
                Assert.Fail($"{label} line {row.LineNumber}: bid rejected <{row.Text}>: {b.Error}");
            if (b.Bits != row.Bid)
                Assert.Fail($"{label} line {row.LineNumber}: bid <{row.Text}> gave {Hex.Format32(b.Bits)}, expected {row.BidHex}");
            var d = ParseResult.DpdParse(row.Text);
            if (d.Error != null)
                Assert.Fail($"{label} line {row.LineNumber}: dpd rejected <{row.Text}>: {d.Error}");
            if (d.Bits != row.Dpd)
                Assert.Fail($"{label} line {row.LineNumber}: dpd <{row.Text}> gave {Hex.Format32(d.Bits)}, expected {row.DpdHex}");
        }
    }
}

/// <summary>
/// The full canonical table: 84,783 rows, read from the same submodule as the
/// rest. It is a separate class only because it is two orders of magnitude
/// bigger than the other four put together, not because it is optional —
/// keeping it here rather than in a file of its own is what lets the two table
/// runners above stay internal to this file.
/// </summary>
public class TestCanonicalCorpus
{
    [Fact]
    public void CanonicalTableDecodesAndReEncodes()
    {
        var rows = Corpus.Load(Corpus.Canonical);
        Assert.Equal(84783, rows.Count);
        TestCorpusVectors.RunDecodeTable(rows, "canonical");
        TestCorpusVectors.RunEncodeTable(rows, "canonical");
    }
}

/// <summary>
/// One row of a <c>text_bid_dpd</c> table: the text, the two encodings, and the
/// <c>status</c> column the input-driven tables carry.
/// </summary>
internal sealed class CorpusRow
{
    internal string Text { get; }
    internal UInt128 Bid { get; }
    internal UInt128 Dpd { get; }
    internal string Status { get; }
    internal int LineNumber { get; }

    /// <summary>The encoding as the corpus spells it: 32 uppercase hex digits.</summary>
    internal string BidHex => Hex.Format32(Bid);
    internal string DpdHex => Hex.Format32(Dpd);

    internal CorpusRow(string text, UInt128 bid, UInt128 dpd, string status, int lineNumber)
    {
        Text = text;
        Bid = bid;
        Dpd = dpd;
        Status = status;
        LineNumber = lineNumber;
    }
}

/// <summary>
/// Hex, in the corpus column form: 32 uppercase digits, most-significant first.
/// </summary>
internal static class Hex
{
    /// <summary>Parse 32 hex digits, with or without a leading <c>0x</c>.</summary>
    internal static UInt128? Parse32(string s)
    {
        string body = (s.StartsWith("0x", StringComparison.Ordinal) || s.StartsWith("0X", StringComparison.Ordinal))
            ? s.Substring(2)
            : s;
        if (body.Length != 32)
            return null;
        if (!UInt128.TryParse(body, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out UInt128 v))
            return null;
        return v;
    }

    /// <summary>Render an encoding as 32 uppercase hex digits.</summary>
    internal static string Format32(UInt128 v) => v.ToString("X32", CultureInfo.InvariantCulture);
}

/// <summary>
/// The shared conformance corpus, read from <c>resources/text_bid_dpd</c> — the
/// <c>decimal128-resources</c> submodule, mounted at the repo root the way
/// every decimal128 port mounts it. Nothing is copied into this repo.
/// </summary>
/// <remarks>
/// <para>
/// The row counts are asserted by the tests, and that is not ceremony: the text
/// column of <c>parse</c> and <c>error</c> is double-quoted with backslash
/// escapes, because those tables must carry the empty string, a leading and a
/// trailing space, an embedded comma, an embedded quote and an embedded
/// backslash. The other three leave it bare. A naive comma split silently
/// corrupts four rows and still passes, since a mangled malformed input fails
/// to parse either way. The row count is what catches it.
/// </para>
/// <para>
/// The directory is resolved from this file's own compile-time path, which is
/// the same trick the Swift port plays with <c>#filePath</c>: tests run out of
/// the build directory, but the source path does not move. An absolute
/// <c>DECIMAL128_RESOURCES</c> overrides it, for a runner that relocates the
/// binaries away from the tree they were built in.
/// </para>
/// </remarks>
internal static class Corpus
{
    internal const string Hundred = "text_bid128_dpd128_100";
    internal const string NonCanonical = "text_bid128_dpd128_noncanonical";
    internal const string Parse = "text_bid128_dpd128_parse";
    internal const string Error = "text_bid128_dpd128_error";
    internal const string Canonical = "text_bid128_dpd128_canonical";

    /// <summary>Where the loader looked, for an error message that names the fix.</summary>
    internal const string ResourcesHint =
        "the decimal128-resources submodule is not checked out: "
        + "run `git submodule update --init --recursive`";

    private static string ThisFileDirectory([CallerFilePath] string path = "")
        => Path.GetDirectoryName(path)!;

    private static string CorpusDirectory
    {
        get
        {
            string? env = Environment.GetEnvironmentVariable("DECIMAL128_RESOURCES");
            if (!string.IsNullOrEmpty(env))
                return Path.Combine(env, "text_bid_dpd");
            // tests/Decimal128.TextCodec.Tests -> tests -> repo root
            string repoRoot = Path.GetFullPath(Path.Combine(ThisFileDirectory(), "..", ".."));
            return Path.Combine(repoRoot, "resources", "text_bid_dpd");
        }
    }

    /// <summary>One table, read off the filesystem.</summary>
    internal static IReadOnlyList<CorpusRow> Load(string name)
    {
        string path = Path.Combine(CorpusDirectory, name + ".csv.txt");
        if (!File.Exists(path))
            Assert.Fail($"{path} could not be read -- {ResourcesHint}");
        return ParseTable(File.ReadAllText(path, Encoding.UTF8), name);
    }

    private static List<CorpusRow> ParseTable(string contents, string name)
    {
        var rows = new List<CorpusRow>();
        int lineNumber = 0;
        foreach (string rawLine in contents.Split('\n'))
        {
            ++lineNumber;
            string line = rawLine;
            while (line.EndsWith('\r'))
                line = line.Substring(0, line.Length - 1);
            line = SkipSpace(line);
            if (line.Length == 0 || line.StartsWith('#'))
                continue;

            Field first = line.StartsWith('"') ? ReadQuoted(line) : ReadField(line);
            string text = first.Value;
            line = first.Rest;

            Field bid = ReadNextField(line);
            Field dpd = ReadNextField(bid.Rest);
            Field status = ReadNextField(dpd.Rest);

            UInt128? bidBits = Hex.Parse32(bid.Value);
            UInt128? dpdBits = Hex.Parse32(dpd.Value);
            if (bidBits == null || dpdBits == null)
            {
                Assert.Fail($"{name}.csv.txt line {lineNumber}: malformed hex columns <{bid.Value}> <{dpd.Value}>");
            }
            rows.Add(new CorpusRow(text, bidBits.Value, dpdBits.Value, status.Value, lineNumber));
        }
        return rows;
    }

    // -- the reader, matching the C, Swift, Kotlin and Java ports -------------

    /// <summary>One field and the unconsumed rest of the line.</summary>
    private readonly record struct Field(string Value, string Rest);

    private static string SkipSpace(string s)
    {
        int i = 0;
        while ((i < s.Length) && ((s[i] == ' ') || (s[i] == '\t')))
            ++i;
        return s.Substring(i);
    }

    /// <summary>
    /// One comma-delimited field, stopping at <c>,</c> or <c>#</c> or end of
    /// line, with surrounding whitespace trimmed. Returns the field and the
    /// unconsumed rest.
    /// </summary>
    private static Field ReadField(string s)
    {
        string start = SkipSpace(s);
        int end = 0;
        while ((end < start.Length) && (start[end] != ',') && (start[end] != '#'))
            ++end;
        int trim = end;
        while ((trim > 0) && ((start[trim - 1] == ' ') || (start[trim - 1] == '\t')))
            --trim;
        return new Field(start.Substring(0, trim), start.Substring(end));
    }

    /// <summary>
    /// Step over a field separator, then read the next field. Yields the empty
    /// string when the row has no further column.
    /// </summary>
    private static Field ReadNextField(string s)
    {
        string rest = SkipSpace(s);
        if (!rest.StartsWith(','))
            return new Field("", rest);
        return ReadField(rest.Substring(1));
    }

    /// <summary>The quoted text column, honouring backslash escapes.</summary>
    private static Field ReadQuoted(string s)
    {
        var outText = new StringBuilder();
        int i = 1; // past the opening quote
        while ((i < s.Length) && (s[i] != '"'))
        {
            char c = s[i];
            ++i;
            if ((c == '\\') && (i < s.Length))
            {
                c = s[i];
                ++i;
            }
            outText.Append(c);
        }
        if ((i < s.Length) && (s[i] == '"'))
            ++i;
        return new Field(outText.ToString(), s.Substring(i));
    }
}

// ---------------------------------------------------------------------------
// Thin wrappers so the tests read the way the codec's own API does.
// ---------------------------------------------------------------------------

internal sealed class ParseResult
{
    internal UInt128 Bits { get; }
    internal string? Error { get; }

    private ParseResult(UInt128 bits, string? error)
    {
        Bits = bits;
        Error = error;
    }

    internal static ParseResult BidParse(string text)
    {
        string? err = Decimal128TextCodec.Bid128Parse(out UInt128 bits, text);
        return new ParseResult(bits, err);
    }

    internal static ParseResult DpdParse(string text)
    {
        string? err = Decimal128TextCodec.Dpd128Parse(out UInt128 bits, text);
        return new ParseResult(bits, err);
    }
}
